import { MatchStateSchema } from '@arenalive/shared';
import type { MatchState } from '@arenalive/volley-stats';

/**
 * Example match of the preview in the editor «Pagina pubblica» when the client has no live match: loaded on demand
 * (own chunk, about 5 KB compressed), generated by `pnpm --filter @arenalive/web sample-match`.
 */
export async function loadSampleMatch(): Promise<MatchState> {
  const json: unknown = (await import('./sampleMatch.json')).default;
  return MatchStateSchema.parse(json);
}
